def find_cheapest_price(n, flights, src, dst, k):
    INF = float("inf")
    price = [INF] * n
    price[src] = 0
    for _ in range(k + 1):
        prev = price[:]                          # read only last round's prices
        for u, v, w in flights:
            if prev[u] + w < price[v]:
                price[v] = prev[u] + w
    return -1 if price[dst] == INF else price[dst]

def find_cheapest_price(n, flights, src, dst, k):
    adj = defaultdict(list)
    for u, v, w in flights:
        adj[u].append((v, w))
    best = [float("inf")] * n
    best[src] = 0
    level = [(src, 0)]
    for _ in range(k + 1):
        nxt = []
        for u, cost in level:
            for v, w in adj[u]:
                if cost + w < best[v]:
                    best[v] = cost + w
                    nxt.append((v, cost + w))
        level = nxt
    return -1 if best[dst] == float("inf") else best[dst]

def find_cheapest_price(n, flights, src, dst, k):
    adj = defaultdict(list)
    for u, v, w in flights:
        adj[u].append((v, w))
    fewest = [float("inf")] * n                  # fewest flights seen per city
    heap = [(0, src, 0)]
    while heap:
        cost, u, used = heapq.heappop(heap)
        if u == dst:
            return cost
        if used >= fewest[u] or used > k:
            continue
        fewest[u] = used
        for v, w in adj[u]:
            heapq.heappush(heap, (cost + w, v, used + 1))
    return -1
